public class Xks43ExceptionHandler {








    @ExceptionHandler(Xks43Exception.class)
    public ResponseEntity<ErrorResponse> handleGlobalException(
            HttpServletRequest request, Xks43Exception e) {
        ErrorCode errorCode = e.getErrorCode();
        log.error("Xks43Exception: {} - {}", errorCode.getCode(), e.getMessage(), e);

        return ResponseEntity
                .status(errorCode.getStatus())
                .body(ErrorResponse.of(
                        errorCode.getCode(),
                        errorCode.getMessage(),
                        errorCode.getStatus(),
                        request.getRequestURI()
                ));
    }








